export function createDebouncer(fn, waitMs, options) {
  if (typeof fn !== 'function') throw new TypeError('fn must be a function');
  if (typeof waitMs !== 'number') throw new TypeError('waitMs must be a number');
  if (!Number.isInteger(waitMs) || waitMs < 0) {
    throw new RangeError('waitMs must be an integer of at least 0');
  }
  if (options !== undefined && (options === null || typeof options !== 'object')) {
    throw new TypeError('options must be an object');
  }

  const settings = options ?? {};
  const leading = settings.leading === true;
  const trailing = settings.trailing !== false;

  let running = false;
  let left = 0;
  let waiting = null;

  const fire = () => {
    const args = waiting;
    waiting = null;
    fn(...args);
  };

  return {
    call(...args) {
      if (!running && leading) fn(...args);
      else if (trailing) waiting = args;
      running = true;
      left = waitMs;
    },
    tick(ms) {
      if (typeof ms !== 'number') throw new TypeError('ms must be a number');
      if (!Number.isInteger(ms) || ms < 0) {
        throw new RangeError('ms must be an integer of at least 0');
      }
      if (!running) return undefined;
      left -= ms;
      if (left <= 0) {
        running = false;
        left = 0;
        if (waiting !== null) fire();
      }
      return undefined;
    },
    cancel() {
      running = false;
      left = 0;
      waiting = null;
      return undefined;
    },
    flush() {
      running = false;
      left = 0;
      if (waiting === null) return false;
      fire();
      return true;
    },
    pending() {
      return waiting !== null;
    },
  };
}
